body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.agenda {
  padding: 0 22px 22px;
  box-sizing: border-box;
}

.head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.head span {
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

h2 {
  margin: 3px 0 4px;
  font-size: 20px;
}

p {
  margin: 0;
  color: #667085;
  font-size: 13px;
}

.count {
  border: 1px solid #d0d5dd;
  border-radius: 999px;
  padding: 8px 12px;
  background: #fff;
  font-size: 12px;
  font-weight: 900;
}

.days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 10px;
}

.day {
  min-height: 180px;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  padding: 10px;
}

.day.today {
  border-color: #111827;
}

.day-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.day-head strong {
  font-size: 13px;
}

.day-head span {
  color: #667085;
  font-size: 11px;
}

.event {
  border: 1px solid #eaecf0;
  border-radius: 7px;
  padding: 8px;
  margin-bottom: 7px;
  background: #f9fafb;
}

.event b {
  display: block;
  font-size: 12px;
}

.event span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 11px;
}

.tag {
  display: inline-block;
  margin-top: 6px;
  font-size: 10px;
  border: 1px solid #d0d5dd;
  border-radius: 999px;
  padding: 3px 6px;
  background: #fff;
}

.empty {
  color: #98a2b3;
  font-size: 12px;
  padding-top: 12px;
}

@media (max-width: 1200px) {
  .days {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 700px) {
  .days {
    grid-template-columns: 1fr;
  }
  .head {
    display: block;
  }
  .count {
    display: inline-block;
    margin-top: 10px;
  }
}

