function dateKey(date) {
  return new Date(date).toISOString().slice(0, 10);
}
function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}
function fmtDay(date) {
  return new Date(date).toLocaleDateString("en-GB", {
    weekday: "short",
    day: "2-digit",
    month: "short"
  });
}
function render(model = {}) {
  const events = model.events || [];
  const today = new Date();
  const days = Array.from({
    length: 7
  }, (_, index) => addDays(today, index));
  document.getElementById("count").innerText = `${events.length} event${events.length === 1 ? "" : "s"}`;
  document.getElementById("days").innerHTML = days.map(day => {
    const key = dateKey(day);
    const dayEvents = events.filter(event => dateKey(event.eventDate) === key);
    return `
      <div class="day ${indexToday(day) ? "today" : ""}">
        <div class="day-head">
          <strong>${fmtDay(day)}</strong>
          <span>${dayEvents.length}</span>
        </div>
        ${dayEvents.length ? dayEvents.map(event => `
              <div class="event">
                <b>${event.title || event.documentNumber}</b>
                <span>${event.subtitle || event.documentNumber || ""}</span>
                <div class="tag">${event.eventType} / ${event.status}</div>
              </div>
            `).join("") : `<div class="empty">No events</div>`}
      </div>
    `;
  }).join("");
}
function indexToday(day) {
  return dateKey(day) === dateKey(new Date());
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

